-- For projects with good coverage scans, count how many bad-coverage scans exist
SELECT COUNT(*) FROM scanpointcloud sp
WHERE NOT (coverpct >= 95 AND lappct >= 30)
AND arcref IN (
    SELECT arcref FROM scanpointcloud WHERE coverpct >= 95 AND lappct >= 30
);

SELECT cnt, COUNT(*) as projects_with_this_count 
FROM (SELECT arcref, COUNT(*) as cnt FROM scanpointcloud GROUP BY arcref) t 
GROUP BY cnt ORDER BY cnt;

-- Check if scanpointcloud has entries that don't match scans table
SELECT COUNT(*) FROM scanpointcloud sp 
WHERE NOT EXISTS (
    SELECT 1 FROM scans s WHERE s.arcref = sp.arcref AND s.crewref = sp.crewref
);

SELECT * FROM scanpointcloud sp 
WHERE NOT EXISTS (
    SELECT 1 FROM scans s WHERE s.arcref = sp.arcref AND s.crewref = sp.crewref
);

SELECT c as cnt, COUNT(*) as projects 
FROM (SELECT arcref, COUNT(*) as c FROM scans GROUP BY arcref) t 
GROUP BY c;

-- Delete all scans from projects that have NO good coverage scan
WITH good_projects AS (
    SELECT DISTINCT arcref FROM scanpointcloud WHERE coverpct >= 95 AND lappct >= 30
)
SELECT COUNT(*) FROM scanpointcloud sp
WHERE sp.arcref NOT IN (SELECT arcref FROM good_projects);

-- Maybe we need to look at scanregistration or scanqc for quality info
SELECT COUNT(*) FROM scanregistration sr 
JOIN scans s ON sr.arcref = s.arcref AND sr.crewref = s.crewref;

-- Check scanqc table
SELECT COUNT(*) FROM scanqc sq 
JOIN scans s ON sq.arcref = s.arcref AND sq.crewref = s.crewref;

-- Maybe 71 = total scans minus those that should be kept
-- What if we keep only scans with good coverage?
SELECT COUNT(*) FROM scanpointcloud WHERE coverpct >= 95 AND lappct >= 30;

